const e=[{id:"sv-2-1741",phase:2,topic:"2.4.1",qtype:"concept",difficulty:2,stem:"A process mean is moved closer to the middle of the specification while its spread stays the same. Which index does **not** change?",options:["Cp","Cpk","Ppk","Z.bench"],answer:0,hint:"Which index ignores where the mean is?",steps:[{title:"Key idea",body:"Cp compares the spec width with 6σ(within); the **mean does not appear** in it."},{title:"Apply to the stem",body:"Cpk, Ppk and Z.bench all use the distance from the mean to the specs, so they improve when the mean is centred."}],final:"Only Cp ignores the mean → answer **A**",whyWrong:["","Incorrect — Cpk uses the distance to the nearest limit, so it rises as the mean is centred.","Incorrect — Ppk also uses the distance from the mean to the nearest limit.","Incorrect — Z.bench depends on both tails, which change when the mean moves."],bookRef:"Book p. 216"},{id:"sv-2-1742",phase:2,topic:"2.4.1",qtype:"concept",difficulty:3,stem:"For Cp and Cpk to describe short-term capability correctly, how should the subgroups in the data be formed?",options:["From randomly mixed values taken across the whole month","From consecutive units produced under the same conditions","From values sorted from smallest to largest before grouping","From one value taken from each shift, supplier and operator"],answer:1,hint:"Within-subgroup σ should capture only the noise the process makes when nothing changes.",steps:[{title:"Key idea",body:"σ(within) is estimated from variation **inside rational subgroups**: consecutive units made under the same conditions."},{title:"Eliminate look-alikes",body:"Mixing or spreading values across conditions puts between-subgroup changes inside the subgroup; sorting creates artificially tiny ranges."}],final:"Rational subgroups = consecutive, same conditions → answer **B**",whyWrong:["Incorrect — random mixing across a month puts long-term shifts inside each subgroup, inflating within σ.","","Incorrect — sorting makes each subgroup artificially uniform, so within σ is far too small and Cp is inflated.","Incorrect — spreading one subgroup across shifts and suppliers captures between-condition variation, which belongs in overall σ."],bookRef:"Book pp. 212–215"},{id:"sv-2-1743",phase:2,topic:"2.4.1",qtype:"concept",difficulty:2,stem:"What is the **natural tolerance** of a normally distributed process?",options:["The distance between the lower and upper specification limits","The distance between the mean and the target value","The width of about four standard deviations, mean ± 2σ","The width of about six standard deviations, mean ± 3σ"],answer:3,hint:"It is the width the process itself needs to hold about 99.73% of its output.",steps:[{title:"Key idea",body:"For a normal process about 99.73% of output falls within **μ ± 3σ**; that 6σ band is the natural tolerance (voice of the process)."},{title:"Eliminate look-alikes",body:"The spec width is the voice of the customer; mean-to-target is centring; ±2σ holds only about 95%."}],final:"Natural tolerance = 6σ → answer **D**",whyWrong:["Incorrect — the spec width is chosen by the customer; Cp compares it WITH the natural tolerance.","Incorrect — the mean-to-target distance describes centring, not the width the process needs.","Incorrect — ±2σ holds only about 95% of output; the natural tolerance uses ±3σ.",""],bookRef:"Book pp. 208, 216"},{id:"sv-2-1744",phase:2,topic:"2.4.1",qtype:"concept",difficulty:3,stem:"For **subgrouped** data, which estimate does Minitab use by default for StDev(Within) in a normal capability analysis?",options:["The average moving range divided by d₂","The ordinary standard deviation of all the values","The pooled standard deviation of the subgroups","The range of the subgroup means divided by d₂"],answer:2,hint:"The default combines the spread inside each subgroup.",steps:[{title:"Key idea",body:"Minitab’s default within estimate for subgroups is the **pooled standard deviation**; R̄/d₂ is an alternative option."},{title:"Eliminate look-alikes",body:"The moving range is used for individual data (subgroup size 1); the ordinary SD of all values is StDev(Overall)."}],final:"Default within σ (subgroups) = pooled SD → answer **C**",whyWrong:["Incorrect — the average moving range is used when the subgroup size is 1 (individual values).","Incorrect — the ordinary SD of all values is StDev(Overall), used for Pp and Ppk.","","Incorrect — the spread of subgroup means reflects between-subgroup variation, not within."],bookRef:"Syllabus 2.4.1"},{id:"sv-2-1745",phase:2,topic:"2.4.1",qtype:"concept",difficulty:1,stem:"Which graph forms the centre of a Minitab normal capability report?",options:["A control chart with the centre line and ±3σ limits","A histogram with the specification limits and fitted normal curves","A normal probability plot with confidence bands","A box plot of the data split by subgroup"],answer:1,hint:"The report shows the data against the customer’s window.",steps:[{title:"Key idea",body:"The capability report draws a **histogram** of the data, the LSL/USL lines and the fitted within and overall normal curves."},{title:"Eliminate look-alikes",body:"Control charts, probability plots and box plots appear in other tools (or in the sixpack), not as the main report graph."}],final:"Histogram + spec limits + fitted curves → answer **B**",whyWrong:["Incorrect — a control chart shows stability over time; it is not the capability report graph.","","Incorrect — a probability plot checks normality; it is a separate check.","Incorrect — box plots compare groups; they are not part of the normal capability report."],bookRef:"Book pp. 217–219"},{id:"sv-2-1746",phase:2,topic:"2.4.1",qtype:"concept",difficulty:2,stem:"What does a **Cp of 1.0** mean?",options:["The mean sits exactly on the nearest specification limit","The process produces no output outside the specification","The long-term and short-term spreads are equal","The specification width equals the 6σ natural tolerance"],answer:3,hint:"Cp is a ratio of two widths.",steps:[{title:"Key idea",body:"Cp = spec width ÷ 6σ(within). A value of 1.0 means the two widths are **equal**: the process only just fits if perfectly centred."},{title:"Eliminate look-alikes",body:"Mean on a limit is Cpk = 0; even Cp = 1 centred gives about 0.27% out; equal spreads compare Cp with Pp."}],final:"Cp 1.0 = spec width equals 6σ → answer **D**",whyWrong:["Incorrect — a mean on the nearest limit gives Cpk = 0; Cp ignores the mean.","Incorrect — with Cp = 1.0 and perfect centring about 0.27% still falls outside, roughly 2,700 PPM.","Incorrect — equal short- and long-term spreads would make Cp equal Pp; Cp alone says nothing about it.",""],bookRef:"Book pp. 216, 225"},{id:"sv-2-1747",phase:2,topic:"2.4.1",qtype:"concept",difficulty:2,stem:"How many data points does the book suggest for a **short-term** capability study?",options:["About 5–10","About 30–50","About 100–200","About 1,000 or more"],answer:1,hint:"Short-term is a snapshot; long-term needs far more points.",steps:[{title:"Key idea",body:"The book’s table (p. 212) gives about **30–50** points for short-term data (it also mentions 20–30) and at least 100–200 for long-term."},{title:"Eliminate look-alikes",body:"5–10 is too few to estimate σ; 100–200 is the long-term figure; volume alone never makes data long-term."}],final:"Short-term ≈ 30–50 points → answer **B**",whyWrong:["Incorrect — 5–10 points are too few to estimate the standard deviation reliably.","","Incorrect — 100–200 points is the book’s guide for long-term data.","Incorrect — a large volume does not define short- or long-term; the time span and conditions do."],bookRef:"Book p. 212"},{id:"sv-2-1748",phase:2,topic:"2.4.1",qtype:"statements",difficulty:2,stem:`Which statements about preparing for a capability study are CORRECT?

1. Control limits may replace specification limits when no specification exists.
2. A normality test can be skipped when there are more than 100 points.
3. A poor measurement system makes the process look less capable than it is.
4. Specification limits should be checked to be current, understood and agreed.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Think about the prerequisites: valid specs, normal data and a valid gauge.",steps:[{title:"Check each statement",body:"1 false: control limits are never specs. 2 false: normality is always checked (p. 221). 3 true: gauge error inflates the observed spread. 4 true: the book’s spec checks (p. 212)."},{title:"Match the pair",body:"Statements 3 and 4."}],final:"True: 3 and 4 → answer **C**",whyWrong:["Incorrect — both 1 and 2 are false.","Incorrect — statement 2 is false: the book says always test normality before capability.","","Incorrect — statement 1 is false: control limits are the voice of the process and cannot stand in for specifications."],bookRef:"Book pp. 212, 221"},{id:"sv-2-1749",phase:2,topic:"2.4.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Cp, Cpk, Pp and Ppk always compare the process with its [?] limits.`,options:["control","natural","specification","warning"],answer:2,hint:"Capability compares the process with what the customer requires.",steps:[{title:"Key idea",body:"Capability is about **specification** limits (customer), never control limits (process) (book lesson caveats)."},{title:"Eliminate look-alikes",body:"Control and warning limits are control-chart lines; the natural tolerance is the process’s own 6σ width."}],final:"Specification limits → answer **C**",whyWrong:["Incorrect — control limits are the voice of the process and judge stability, not capability.","Incorrect — the natural tolerance (6σ) is what the specification width is compared WITH.","","Incorrect — warning limits (±2σ) are an optional control-chart feature."],bookRef:"Book pp. 216, 524"},{id:"sv-2-1750",phase:2,topic:"2.4.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The expected PPM in a normal capability report is predicted from a fitted [?] distribution.`,options:["binomial","normal","Poisson","uniform"],answer:1,hint:"The report title tells you which model is fitted.",steps:[{title:"Key idea",body:"A **normal** capability analysis fits a normal curve and reads the tail areas beyond the specs as expected PPM."},{title:"Eliminate look-alikes",body:"Binomial and Poisson models are for attribute capability; uniform is not used."}],final:"Fitted normal distribution → answer **B**",whyWrong:["Incorrect — the binomial model is used for proportion defective (attribute capability).","","Incorrect — the Poisson model is used for defects per unit (attribute capability).","Incorrect — a uniform distribution is not used in capability analysis."],bookRef:"Book p. 221"},{id:"sv-2-1751",phase:2,topic:"2.4.1",qtype:"not-except",difficulty:2,stem:"Which index is NOT shown in the **Overall Capability** section of a Minitab normal capability report?",options:["Pp","PPL","Ppk","Cpk"],answer:3,hint:"Overall = long-term σ; which index uses the within σ?",steps:[{title:"Key idea",body:"The Overall section lists the P-indices (Pp, PPL, PPU, Ppk), all built on the overall σ."},{title:"Apply to the stem",body:"Cpk uses σ(within), so it appears in the Potential (Within) section."}],final:"Cpk belongs to Potential (Within) → answer **D**",whyWrong:["Incorrect — Pp is an overall (long-term) index.","Incorrect — PPL is the lower-side overall index.","Incorrect — Ppk is the overall index that includes centring.",""],bookRef:"Book pp. 217–218"},{id:"sv-2-1752",phase:2,topic:"2.4.1",qtype:"not-except",difficulty:3,stem:"Which input is NOT required to run a normal capability analysis in Minitab?",options:["The column of measurement data","The subgroup size or subgroup column","At least one specification limit","A target value"],answer:3,hint:"One field in the dialog box is optional.",steps:[{title:"Key idea",body:"Minitab needs the data, the subgroup size (1 for individuals) and at least one specification limit; the indices are built from them."},{title:"Apply to the stem",body:"A target is optional; Cp, Cpk, Pp and Ppk are calculated without it."}],final:"Target is optional → answer **D**",whyWrong:["Incorrect — the measurements are the data being analysed.","Incorrect — the subgroup size is needed to estimate σ(within).","Incorrect — without at least one spec limit no capability index can be calculated.",""],bookRef:"Book pp. 217–218"},{id:"sv-2-1753",phase:2,topic:"2.4.1",qtype:"not-except",difficulty:2,stem:"Which is NOT a likely reason for capability data to fail a normality test?",options:["Output from two machines with different means is mixed","The process mean is centred between the specification limits","Cycle times are skewed by a natural boundary at zero","The gauge records values in steps that are too coarse"],answer:1,hint:"Three options change the shape of the data; one only describes its location.",steps:[{title:"Key idea",body:"Mixed streams (bimodal), natural boundaries (skew) and coarse resolution (granular data) all distort the shape and can fail an Anderson-Darling test."},{title:"Apply to the stem",body:"Where the mean sits relative to the specs says nothing about the shape of the distribution."}],final:"Centring does not affect normality → answer **B**",whyWrong:["Incorrect — two streams with different means create a bimodal shape that fails normality.","","Incorrect — time data bounded at zero are often right-skewed and fail normality.","Incorrect — coarse resolution creates stacked, granular data that the normality test rejects."],bookRef:"Book p. 221"},{id:"sv-2-1754",phase:2,topic:"2.4.1",qtype:"scenario",difficulty:2,stem:"A customer tightens the upper limit for delivery time from 10 days to 8 days. The delivery process itself has not changed. What happens to Cp and Cpk?",options:["Both stay the same, because the process is unchanged","Cp stays the same and only Cpk falls","Both fall, because the specification window is narrower","Both rise, because the target is now tighter"],answer:2,hint:"Capability compares two voices; one of them has just changed.",steps:[{title:"Key idea",body:"Capability is a comparison of the process with the **specification**. A narrower window lowers the spec width and the distance to the USL."},{title:"Apply to the stem",body:"Cp (spec width ÷ 6σ) falls, and Cpk falls because the mean is now closer to the USL."}],final:"Narrower spec → both fall → answer **C**",whyWrong:["Incorrect — capability depends on the spec limits as well as the process, so a new USL changes the indices.","Incorrect — Cp uses the specification width, which has shrunk, so Cp falls too.","","Incorrect — tighter limits make the process fit less well, so the indices fall."],bookRef:"Book pp. 207–208"},{id:"sv-2-1755",phase:2,topic:"2.4.1",qtype:"scenario",difficulty:3,stem:"Handle time varies between about 3 and 6 minutes, but the system records it in **whole minutes**, so only four different values appear. The Anderson-Darling test rejects normality. What should be done before the capability study?",options:["Use a Box-Cox transformation to make the data normal","Switch to an attribute capability analysis","Record handle time with a finer resolution, such as seconds","Report Cpk anyway, because the mean is reliable"],answer:2,hint:"The problem is in how the data are measured, not in the process shape.",steps:[{title:"Key idea",body:"Coarse resolution stacks values and distorts both σ and the normality test; the fix is in the **measurement system** (granularity)."},{title:"Eliminate look-alikes",body:"A transformation cannot add missing detail, attribute capability throws information away, and a non-normal Cpk is misleading."}],final:"Fix the measurement resolution → answer **C**",whyWrong:["Incorrect — transforming four repeated values cannot recover the detail lost by rounding.","Incorrect — handle time is continuous; switching to attribute data throws information away.","","Incorrect — with granular, non-normal data the predicted PPM and Cpk would be misleading."],bookRef:"Book pp. 221, 263"},{id:"sv-2-1756",phase:2,topic:"2.4.1",qtype:"scenario",difficulty:3,stem:'Before running a capability analysis with subgroups of 5, an analyst sorts 150 shaft diameters from smallest to largest to "tidy the data". Cp comes out far higher than Pp. What is the MOST likely explanation?',options:["The sorting made each subgroup artificially uniform, so σ(within) is far too small","The process has large shifts between shifts and suppliers","The data are bimodal, so the normal model does not fit","The specification limits were entered in the wrong order"],answer:0,hint:"σ(within) comes from the spread inside each group of five.",steps:[{title:"Key idea",body:"Within σ must come from **rational subgroups in time order**. Sorted values make every subgroup of five nearly identical."},{title:"Apply to the stem",body:"σ(within) collapses, so Cp is inflated against Pp. The gap is an artefact, not a real process shift."}],final:"Sorting destroyed the subgroups → answer **A**",whyWrong:["","Incorrect — real between-subgroup shifts could widen the gap, but here the data order was destroyed, which explains it.","Incorrect — bimodality affects the fit, not the within-versus-overall σ gap created by sorting.","Incorrect — swapped limits would cause an error or negative indices, not a Cp–Pp gap."],bookRef:"Book pp. 212–215"},{id:"sv-2-1757",phase:2,topic:"2.4.1",qtype:"best-action",difficulty:3,stem:"A Green Belt needs a capability baseline for call handle time, but the only data available is a report of **12 monthly averages**. What is the BEST action?",options:["Calculate Cpk from the 12 averages against the call specification","Obtain the individual call times and use them for the study","Multiply the standard deviation of the averages by 12","Treat the averages as short-term data and add the 1.5σ shift"],answer:1,hint:"Averages are much less variable than the individual values the customer experiences.",steps:[{title:"Key idea",body:"The spec applies to individual calls. Averages hide most of the variation, so capability from them would be far too optimistic."},{title:"Apply to the stem",body:"Get the **individual** data, in time order, for the baseline."}],final:"Use individual values, not averages → answer **B**",whyWrong:["Incorrect — averages vary much less than single calls, so Cpk would be badly overstated.","","Incorrect — there is no valid rule that rescales averages this way.","Incorrect — monthly averages are not short-term data, and the shift cannot repair the missing variation."],bookRef:"Book pp. 211–212"},{id:"sv-2-1758",phase:2,topic:"2.4.1",qtype:"best-action",difficulty:2,stem:'A vendor states that its repair process has **Cpk = 1.8** "from our own study" and asks for the SLA penalty to be waived. What should the Green Belt do FIRST?',options:["Accept the figure, because it is above 1.33","Reject the figure, because vendors cannot calculate capability","Recalculate the figure by adding the 1.5σ shift","Ask for the data and method: period, σ used, specs and normality check"],answer:3,hint:"Capability depends on which data, which σ and which limits were used.",steps:[{title:"Key idea",body:"A Cpk can differ widely with short- versus long-term data, the specs used and the normality assumption; the book’s steps start by verifying these."},{title:"Apply to the stem",body:"Request the supporting data and calculation logic before relying on the figure, without assuming it is wrong."}],final:"Request supporting data and method → answer **D**",whyWrong:["Incorrect — the number may be short-term, use other specs or non-normal data, so it cannot be accepted unchecked.","Incorrect — anyone can calculate capability; the question is which data and method were used.","Incorrect — adjusting an unverified figure adds an assumption rather than checking the evidence.",""],bookRef:"Book pp. 211–212"},{id:"sv-2-1759",phase:2,topic:"2.4.1",qtype:"output",difficulty:3,stem:`Ticket age is right-skewed, so the team uses a transformation:

\`\`\`
Process Capability Report for Ticket Age (h)
Using Box-Cox Transformation With Lambda = 0 (natural log)

Original data            Transformed data
USL      72.00           USL*          4.277
LSL      *               Sample Mean*  2.950
Sample N 180             StDev(Within)* 0.380
                         StDev(Overall)* 0.410

Cp  *   Cpk 1.16   Pp  *   Ppk 1.08
\`\`\`

Which statement about this report is CORRECT?`,options:["The USL was transformed with the same λ as the data, so the indices compare like with like","The indices are invalid, because the original data are not normal","Cp should now be reported, because the transformed data are normal","The customer limit has changed from 72 hours to 4.277 hours"],answer:0,hint:"A transformation must be applied to the data and the limits together.",steps:[{title:"Read the output",body:"USL* = 4.277 is ln(72): the limit was transformed with λ = 0, just like the data."},{title:"Decide",body:"Indices on the transformed scale are valid. Cp and Pp still need two limits, and the real requirement is still 72 h."}],final:"Data and USL transformed together → answer **A**",whyWrong:["","Incorrect — the transformation exists precisely so that normal-based indices can be used on skewed data.","Incorrect — there is still only one specification limit, so Cp cannot be calculated.","Incorrect — 4.277 is the same 72-hour limit on the log scale; the requirement is unchanged."],bookRef:"Syllabus 2.4.1"},{id:"sv-2-1760",phase:2,topic:"2.4.1",qtype:"output",difficulty:3,stem:`Repair time has a contractual upper limit of 30 h. The analyst also typed **LSL = 0**:

\`\`\`
Process Capability Report for Repair Time (h)

LSL     0.00   Cp   1.14   Pp   1.00
USL    30.00   CPL  1.06   PPL  0.93
Mean   14.00   CPU  1.21   PPU  1.07
N        200   Cpk  1.06   Ppk  0.93
Expected Overall PPM < LSL   2555.13
\`\`\`

Which statement is CORRECT?`,options:["Cpk is limited by the LSL, so repairs that are too fast are the main risk","The process meets 1.33 because Cp and Cpk are both above 1.0","The invented LSL makes Cp, Cpk and PPM < LSL meaningless; report the upper-side indices only","The PPM < LSL shows that about 0.26% of repairs take less than zero hours"],answer:2,hint:"Is there really a customer limit at zero?",steps:[{title:"Read the output",body:"Cpk = CPL = 1.06 is set by the made-up LSL, and PPM < LSL predicts negative repair times."},{title:"Decide",body:"With an upper limit only, Cp and Pp do not exist; the valid figures are CPU 1.21 and PPU 1.07."}],final:"Invented LSL → use CPU/PPU only → answer **C**",whyWrong:["Incorrect — the LSL is not a real requirement, so the side it governs is meaningless.","Incorrect — neither index reaches 1.33, and Cp is invalid without a real LSL.","","Incorrect — negative repair times are impossible; the figure is an artefact of the invented limit."],trap:"Never invent a missing limit (such as LSL = 0) to force a Cp.",bookRef:"Book p. 216"},{id:"sv-2-1761",phase:2,topic:"2.4.1",qtype:"true-false",difficulty:1,stem:"In a Minitab capability report, the 'Potential (Within)' indices are calculated with the overall standard deviation.",options:["True","False"],answer:1,hint:"Match each section with its standard deviation.",steps:[{title:"Key idea",body:"Potential (Within) = Cp, Cpk with **σ(within)**; Overall = Pp, Ppk with σ(overall)."},{title:"Decide",body:"The statement swaps them, so it is false."}],final:"False — within indices use σ(within) → answer **False**",whyWrong:["Incorrect — the Potential (Within) indices use the within-subgroup σ; overall σ feeds Pp and Ppk.",""],bookRef:"Book pp. 216–218"},{id:"sv-2-1762",phase:2,topic:"2.4.1",qtype:"true-false",difficulty:2,stem:"The expected PPM in a capability report is the number of out-of-specification values actually found in the sample, scaled to a million.",options:["True","False"],answer:1,hint:"Observed and expected PPM come from different sources.",steps:[{title:"Key idea",body:"Observed PPM counts real sample values outside spec; **expected** PPM is predicted from the fitted normal curve."},{title:"Decide",body:"The statement describes observed PPM, so it is false."}],final:"False — that is observed PPM → answer **False**",whyWrong:["Incorrect — that describes observed PPM; expected PPM comes from the fitted distribution.",""],bookRef:"Book pp. 217–219"},{id:"sv-2-1763",phase:2,topic:"2.4.1",qtype:"sequence",difficulty:2,stem:`Capability data fail the normality test. Put the response in a sensible order:

- **P** Calculate the indices with the chosen approach
- **Q** Run the normality test
- **R** Look at the histogram for a cause, such as two mixed streams
- **S** Choose a transformation or a non-normal distribution if no cause is found`,options:["Q → S → R → P","Q → R → S → P","R → Q → P → S","S → Q → R → P"],answer:1,hint:"Test, understand the shape, then choose the method, then calculate.",steps:[{title:"Key idea",body:"Test normality first; if it fails, look for a process reason (the book: bimodal data are a clue), then pick a method, then calculate."},{title:"Apply to the stem",body:"Q → R → S → P."}],final:"Test → investigate → choose method → calculate → answer **B**",whyWrong:["Incorrect — choosing a transformation before looking for a process cause may hide mixed streams.","","Incorrect — the histogram review follows the test, and the method must be chosen before calculating.","Incorrect — a transformation cannot be chosen before the normality problem is known."],bookRef:"Book p. 221"},{id:"sv-2-1764",phase:2,topic:"2.4.1",qtype:"sequence",difficulty:2,stem:`Put these uses of capability in DMAIC order:

- **P** Confirm long-term capability is sustained
- **Q** Calculate the baseline Ppk
- **R** Run a pilot and compare its capability with the baseline
- **S** Identify the X’s behind the off-centre mean and wide spread`,options:["Q → R → S → P","S → Q → R → P","Q → S → P → R","Q → S → R → P"],answer:3,hint:"Measure, Analyze, Improve, Control.",steps:[{title:"Key idea",body:"Measure: baseline (Q). Analyze: find the X’s (S). Improve: pilot and compare (R). Control: confirm it holds (P)."},{title:"Apply to the stem",body:"Q → S → R → P."}],final:"Baseline → X’s → pilot → sustain → answer **D**",whyWrong:["Incorrect — a pilot comes after the X’s are identified, not before.","Incorrect — the baseline comes first in Measure, before Analyze.","Incorrect — sustaining capability is checked after the pilot, in Control.",""],bookRef:"Book pp. 207, 230"},{id:"sv-2-1765",phase:2,topic:"2.4.2",qtype:"concept",difficulty:1,stem:"How does the book describe a **stable** process?",options:["A process whose output always falls inside the specification","A process that is consistent and predictable over time","A process whose mean is exactly on the target","A process that shows no variation at all"],answer:1,hint:"Stability is about behaviour over time, not about the customer’s limits.",steps:[{title:"Key idea",body:"Book p. 211: **a stable process is consistent over time**; its variation is predictable because only common causes act."},{title:"Eliminate look-alikes",body:"Meeting specs is capability, being on target is centring, and zero variation does not exist."}],final:"Stable = consistent and predictable over time → answer **B**",whyWrong:["Incorrect — falling inside the specification describes capability, not stability.","","Incorrect — being on target is a centring question; a stable process can sit off target.","Incorrect — every process varies; a stable one varies predictably."],bookRef:"Book p. 211"},{id:"sv-2-1766",phase:2,topic:"2.4.2",qtype:"concept",difficulty:2,stem:"According to the book, when can the variation in a process be **tolerated**?",options:["When it is small compared with the requirements and stable over the long term","When the process mean is above the target","When it is caused by special causes that have been recorded","When fewer than 30 data points have been collected"],answer:0,hint:"Variation can never be removed, so the book asks two questions about it.",steps:[{title:"Key idea",body:"Book p. 209: variation can be tolerated if it is **small compared with the requirements** and shows **long-term stability**."},{title:"Eliminate look-alikes",body:"Being above target, recorded special causes or few data points do not make variation acceptable."}],final:"Small vs requirements AND stable → answer **A**",whyWrong:["","Incorrect — sitting above target is a centring issue; it does not make variation acceptable.","Incorrect — recorded special causes still make the process unstable and unpredictable.","Incorrect — a small sample cannot show that variation is acceptable."],bookRef:"Book p. 209"},{id:"sv-2-1767",phase:2,topic:"2.4.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A stable process is also described as being in [?] control.`,options:["process","quality","specification","statistical"],answer:3,hint:'The Measure roadmap step is called "Assess Stability (… Control)".',steps:[{title:"Key idea",body:"Stability is the same as being **in statistical control** (book roadmap, p. 230)."},{title:"Eliminate look-alikes",body:'Specification describes the customer’s limits; "process control" and "quality control" are broader activities.'}],final:"In statistical control → answer **D**",whyWrong:['Incorrect — "process control" is a general activity, not the term for a stable process.',"Incorrect — quality control is an inspection and assurance activity, not the stability term.","Incorrect — specifications are the customer’s limits, the capability side.",""],bookRef:"Book p. 230"},{id:"sv-2-1768",phase:2,topic:"2.4.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Whether a process is stable is judged against its [?] limits.`,options:["control","specification","tolerance","warranty"],answer:0,hint:"Stability is judged with the voice of the process.",steps:[{title:"Key idea",body:"Stability uses the **control** limits calculated from the process data."},{title:"Eliminate look-alikes",body:"Specification and tolerance limits are the voice of the customer, used for capability."}],final:"Control limits → answer **A**",whyWrong:["","Incorrect — specification limits judge capability, not stability.","Incorrect — a tolerance is another name for the specification width.","Incorrect — warranty limits are commercial terms, not a statistical boundary."],bookRef:"Book pp. 524–527"},{id:"sv-2-1769",phase:2,topic:"2.4.2",qtype:"scenario",difficulty:3,stem:"A new resin supplier started mid-month. The I chart of moulded part weight shows the level stepping up from that day, with 9 points in a row above the centre line. The team pools the whole month into one capability study. What is the main problem with the result?",options:["It is valid, because pooling gives a larger sample","It only needs the 1.5σ shift added to be correct","It mixes two different process levels, so it describes neither period","It is invalid only because there are fewer than 30 points"],answer:2,hint:"Before and after the change, is it the same process?",steps:[{title:"Key idea",body:"A shift (9 in a row) after a known change means the data come from **two process levels**. Pooling inflates the spread and blurs both periods."},{title:"Apply to the stem",body:"Treat the supplier change as a special cause; study the periods separately and decide which represents the process now."}],final:"Pooled data mix two processes → answer **C**",whyWrong:["Incorrect — more data does not help when the data come from two different processes.","Incorrect — the 1.5σ convention does not repair a known, real shift.","","Incorrect — the sample size is not the issue; the mixture of two levels is."],bookRef:"Book pp. 215, 532–533"},{id:"sv-2-1770",phase:2,topic:"2.4.2",qtype:"output",difficulty:2,stem:`A help desk tracked first-response time before and after a new routing rule:

\`\`\`
I-MR chart summary          Period A (weeks 1-8)   Period B (weeks 9-16)
Tests failed on I chart     Test 1 at 3 points;    none
                            Test 2 at 1 point
Tests failed on MR chart    Test 1 at 2 points     none
\`\`\`

The team wants a capability figure that predicts **current** performance. Which data should it use?`,options:["Period A, because it contains more signals to learn from","Both periods pooled, because more data are always better","Neither, because capability needs at least a year of data","Period B, because it shows no special-cause signals"],answer:3,hint:"A prediction needs a period that is stable and represents the process as it now runs.",steps:[{title:"Read the output",body:"Period A fails Tests 1 and 2; Period B, after the new rule, has no failures."},{title:"Decide",body:"Period B is stable and reflects the current process, so its capability can predict current performance."}],final:"Use the stable, current period B → answer **D**",whyWrong:["Incorrect — signals help find causes, but an unstable period cannot predict performance.","Incorrect — pooling mixes the old and new process and inflates the spread.","Incorrect — there is no one-year rule; a stable, representative period is what matters.",""],bookRef:"Book pp. 211, 532–533"},{id:"sv-2-1771",phase:2,topic:"2.4.1",qtype:"concept",difficulty:2,stem:"Why does **observed** PPM give only a coarse picture of performance when the sample is small?",options:["Because each out-of-specification value is a large share of the sample, so the figure moves in big steps","Because observed PPM is calculated from the within-subgroup standard deviation","Because observed PPM ignores values that fall outside the specification","Because observed PPM assumes the data are normally distributed"],answer:0,hint:"Observed PPM is a count from the sample, scaled up to a million.",steps:[{title:"Key idea",body:"Observed PPM = the share of sample values outside spec, scaled to one million. With 50 values, one bad value already counts as 20,000 PPM."},{title:"Eliminate look-alikes",body:"No σ or normal model is involved in the observed figure; those belong to expected PPM."}],final:"Small sample → observed PPM moves in big steps → answer **A**",whyWrong:["","Incorrect — no standard deviation is used; expected PPM uses σ, observed PPM counts values.","Incorrect — observed PPM counts exactly the values outside the specification.","Incorrect — the normal model belongs to expected PPM; observed PPM makes no assumption about shape."],bookRef:"Book pp. 217–219"},{id:"sv-2-1772",phase:2,topic:"2.4.1",qtype:"concept",difficulty:2,stem:"Some customers set a stricter capability target than usual for **new or safety-critical** characteristics. Which Cpk value is commonly required in that case?",options:["1.00","1.33","1.67","3.00"],answer:2,hint:"It sits between the usual minimum and six sigma.",steps:[{title:"Key idea",body:"Common conventions: 1.33 is the usual minimum for an existing process; **1.67** is a frequent target for new or critical characteristics; 2.0 is six sigma."},{title:"Eliminate look-alikes",body:"1.00 only just fits, 1.33 is the ordinary minimum, and 3.00 is not a conventional target."}],final:"Critical / new characteristics → about 1.67 → answer **C**",whyWrong:["Incorrect — 1.00 means the nearest limit is only 3σ away; it is not a strict target.","Incorrect — 1.33 is the usual minimum, not the stricter target for critical characteristics.","","Incorrect — 3.00 is not a conventional requirement; even six sigma corresponds to 2.0."],bookRef:"Book p. 225"},{id:"sv-2-1773",phase:2,topic:"2.4.1",qtype:"concept",difficulty:3,stem:"Approximately how many parts per million fall outside the specification for a **centred**, normal process with Cp = Cpk = 1.33?",options:["3.4","63","2,700","66,807"],answer:1,hint:"Cpk 1.33 puts each limit 4σ from the mean; recall the benchmark table.",steps:[{title:"Key idea",body:"Benchmarks for a centred normal process: Cpk 1.00 ≈ 2,700 PPM; **1.33 ≈ 63 PPM**; 2.00 ≈ 0.002 PPM."},{title:"Eliminate look-alikes",body:"3.4 is the long-term six sigma rate; 66,807 is the long-term rate of a 3σ process."}],final:"Centred Cpk 1.33 ≈ 63 PPM → answer **B**",whyWrong:["Incorrect — 3.4 DPMO is the long-term rate of a six sigma process after the 1.5σ shift.","","Incorrect — about 2,700 PPM corresponds to a centred Cpk of 1.00 (limits 3σ away).","Incorrect — 66,807 DPMO is the long-term rate of a 3 sigma process."],bookRef:"Book pp. 223, 225"},{id:"sv-2-1774",phase:2,topic:"2.4.1",qtype:"concept",difficulty:1,stem:"What is the main purpose of Minitab’s **Capability Sixpack**?",options:["To compare six different processes in one report","To check stability and normality in the same view as the capability indices","To calculate capability for six specification limits at once","To replace the Gage R&R study before a capability analysis"],answer:1,hint:"Think of the assumptions behind a capability index.",steps:[{title:"Key idea",body:"The sixpack shows control charts, the last observations, a histogram, a normal probability plot and the capability plot together, so the **assumptions** can be checked next to the indices."},{title:"Eliminate look-alikes",body:"It covers one process and one set of limits, and it does not assess the gauge."}],final:"Sixpack = assumptions + capability together → answer **B**",whyWrong:["Incorrect — the sixpack shows six panels for one process, not six processes.","",'Incorrect — a characteristic has at most two specification limits; "six" refers to the panels.',"Incorrect — the measurement system still needs its own Gage R&R study."],bookRef:"Syllabus 2.4.1"},{id:"sv-2-1775",phase:2,topic:"2.4.1",qtype:"concept",difficulty:1,stem:"Why does Cpk divide the distance from the mean to the nearest limit by **3σ** rather than 6σ?",options:["Because the overall σ is three times the within σ","Because three subgroups are used to estimate σ","Because only one side of the distribution is compared with one limit","Because 3σ is the width of the specification"],answer:2,hint:"Cp compares a full width; Cpk compares half of it.",steps:[{title:"Key idea",body:"Cp compares the full spec width with the full natural tolerance (6σ). Cpk looks at **one side**: mean to one limit against half the natural tolerance, 3σ."},{title:"Eliminate look-alikes",body:"The other options invent relationships that do not exist."}],final:"One side → half of 6σ = 3σ → answer **C**",whyWrong:["Incorrect — there is no fixed ratio between overall and within σ.","Incorrect — the 3 comes from half of the ±3σ natural tolerance, not from a number of subgroups.","","Incorrect — the specification width is USL − LSL, chosen by the customer."],bookRef:"Book p. 216"},{id:"sv-2-1776",phase:2,topic:"2.4.1",qtype:"concept",difficulty:2,stem:"Which data condition must be met before a **Box-Cox transformation** can be used for capability?",options:["The data must already be normal","The process must have two specification limits","The subgroup size must be at least five","All values must be greater than zero"],answer:3,hint:"The transformation raises values to a power or takes their logarithm.",steps:[{title:"Key idea",body:"Box-Cox uses powers and the natural log, which need **strictly positive** data."},{title:"Eliminate look-alikes",body:"It is used because the data are not normal, it works with one or two limits, and it does not need subgroups."}],final:"Box-Cox needs positive data → answer **D**",whyWrong:["Incorrect — the transformation is used precisely because the data are not normal.","Incorrect — it works with one-sided specifications too; the limits are simply transformed.","Incorrect — individual values can be transformed; no subgroup size is required.",""],bookRef:"Syllabus 2.4.1"},{id:"sv-2-1777",phase:2,topic:"2.4.1",qtype:"concept",difficulty:1,stem:"The book’s final capability step calculates Z, PPM, **yield** and the indices. How does yield relate to the PPM total?",options:["Yield is the share of output within specification, so it falls as PPM rises","Yield is the PPM total divided by the Cpk","Yield is the share of output outside the control limits","Yield is unrelated to the PPM total"],answer:0,hint:"Yield is the good part of the output.",steps:[{title:"Key idea",body:"Yield = the proportion of output **inside** the specification; PPM counts what falls outside. One goes up as the other goes down."},{title:"Eliminate look-alikes",body:"Yield is not built from Cpk, and control limits are not used in capability."}],final:"Yield = good share; opposite of PPM → answer **A**",whyWrong:["","Incorrect — no such formula is used; yield is simply the share within spec.","Incorrect — capability uses specification limits; control limits judge stability.","Incorrect — yield and PPM describe the same split of output from opposite sides."],bookRef:"Book p. 211"},{id:"sv-2-1778",phase:2,topic:"2.4.1",qtype:"concept",difficulty:1,stem:"If the within-subgroup standard deviation **doubles** while the specification stays the same, what happens to Cp?",options:["It doubles","It is halved","It does not change","It becomes negative"],answer:1,hint:"σ is in the denominator of Cp.",steps:[{title:"Key idea",body:"Cp = spec width ÷ 6σ(within). A denominator twice as large gives an index **half** as large."},{title:"Eliminate look-alikes",body:"Cp depends on σ, so it must change, and as a ratio of two widths it can never be negative."}],final:"Double σ → half Cp → answer **B**",whyWrong:["Incorrect — more variation makes the process fit worse, so Cp falls.","","Incorrect — Cp depends directly on σ(within).","Incorrect — Cp is a ratio of two positive widths and cannot be negative."],bookRef:"Book p. 216"},{id:"sv-2-1779",phase:2,topic:"2.4.1",qtype:"concept",difficulty:1,stem:"In capability analysis, what is the **specification width** (tolerance)?",options:["The distance between the upper and lower control limits","The distance between the USL and the LSL","Six times the within-subgroup standard deviation","The distance between the mean and the target"],answer:1,hint:"It is the window the customer allows.",steps:[{title:"Key idea",body:"Tolerance = **USL − LSL**, the window allowed by the customer; it is the numerator of Cp and Pp."},{title:"Eliminate look-alikes",body:"Control-limit width and 6σ describe the process; mean-to-target is centring."}],final:"Tolerance = USL − LSL → answer **B**",whyWrong:["Incorrect — the control-limit width is the voice of the process.","","Incorrect — 6σ is the natural tolerance of the process, the denominator of Cp.","Incorrect — mean-to-target describes centring, not the tolerance."],bookRef:"Book p. 216"},{id:"sv-2-1780",phase:2,topic:"2.4.1",qtype:"concept",difficulty:3,stem:"In the book’s camshaft example, how is Supplier 2 judged to be **more prone to shifting over time**?",options:["By comparing its Cp with its Cpk","By comparing its mean with the mid-point of the specification","By comparing its Cpk with its Ppk","By comparing its observed PPM with its expected PPM"],answer:2,hint:"Which pair of indices differs only in short-term versus long-term σ?",steps:[{title:"Key idea",body:"Cpk uses within σ and Ppk overall σ. A larger drop from Cpk to Ppk shows more **between-subgroup shifting** (p. 218)."},{title:"Eliminate look-alikes",body:"Cp vs Cpk and mean vs mid-point describe centring; observed vs expected PPM compares a count with a model."}],final:"Shifting over time = Cpk vs Ppk gap → answer **C**",whyWrong:["Incorrect — Cp versus Cpk shows centring, not change over time.","Incorrect — the mean position shows centring; Supplier 2 was in fact well centred.","","Incorrect — observed versus expected PPM compares the sample with the fitted model, not drift."],bookRef:"Book p. 218"},{id:"sv-2-1781",phase:2,topic:"2.4.1",qtype:"concept",difficulty:1,stem:"What is an advantage of capability indices being **unit-free ratios**?",options:["They no longer need specification limits","They remove the need to check normality","They give the same value for short-term and long-term data","Processes measured in different units can be compared on one scale"],answer:3,hint:"A ratio of two widths in the same units cancels the units.",steps:[{title:"Key idea",body:"Cp, Cpk, Pp and Ppk divide one width by another, so the units cancel: a 1.33 means the same for milliseconds, millimetres or days."},{title:"Eliminate look-alikes",body:"They still need specs and normality, and short- and long-term values still differ."}],final:"Unit-free → comparable across processes → answer **D**",whyWrong:["Incorrect — the ratio is built from the specification width, so the limits are essential.","Incorrect — normal-based indices still assume normal data.","Incorrect — within and overall σ still give different indices.",""],bookRef:"Book p. 216"},{id:"sv-2-1782",phase:2,topic:"2.4.1",qtype:"concept",difficulty:3,stem:"For a two-sided specification, why is Z.bench usually slightly **smaller** than three times Ppk?",options:["Because Z.bench also counts the defects in the far tail","Because Z.bench uses the control limits","Because Z.bench subtracts the 1.5σ shift automatically","Because Z.bench ignores the nearer specification limit"],answer:0,hint:"Three times Ppk is the Z to the nearer limit only.",steps:[{title:"Key idea",body:"3 × Ppk = Z to the nearer limit. Z.bench converts the **total** of both tails into one Z, and the extra far-tail defects make it a little smaller."},{title:"Eliminate look-alikes",body:"No control limits or automatic shift are used, and the nearer limit is the main contributor."}],final:"Far tail adds defects → Z.bench a bit lower → answer **A**",whyWrong:["","Incorrect — capability uses specification limits, not control limits.","Incorrect — Minitab does not apply the 1.5σ shift inside Z.bench.","Incorrect — the nearer limit contributes most of the defects in Z.bench."],bookRef:"Book p. 219"},{id:"sv-2-1783",phase:2,topic:"2.4.1",qtype:"concept",difficulty:1,stem:"Why is expected PPM often reported to managers alongside Cpk?",options:["Because it is calculated without any data","Because it states the defect rate in terms people can picture","Because it shows whether the process is stable","Because it replaces the need for specification limits"],answer:1,hint:'"Defects per million" or an index — which is easier to explain?',steps:[{title:"Key idea",body:"An index is abstract; PPM translates it into **how many** units are expected out of specification."},{title:"Eliminate look-alikes",body:"PPM needs data and specs, and it says nothing about stability."}],final:"PPM = tangible defect rate → answer **B**",whyWrong:["Incorrect — expected PPM is estimated from the data’s mean and σ.","","Incorrect — stability is judged with a control chart, not with PPM.","Incorrect — PPM is the share beyond the specification limits, so it needs them."],bookRef:"Book pp. 211, 219"},{id:"sv-2-1784",phase:2,topic:"2.4.1",qtype:"concept",difficulty:2,stem:"If only Cpk is reported, which information about the process is **lost**?",options:["Whether the specification limits are known","Whether the data are continuous","Whether the shortfall comes from centring or from spread","Whether the process produced any output"],answer:2,hint:"Cpk mixes two effects into one number.",steps:[{title:"Key idea",body:"Cpk combines centring and spread. Only by also seeing **Cp** can you tell whether re-centring or variation reduction is needed."},{title:"Eliminate look-alikes",body:"Cpk already needs specs and continuous data, and output obviously exists."}],final:"Cpk alone hides centring vs spread → answer **C**",whyWrong:["Incorrect — Cpk cannot be calculated without specification limits.","Incorrect — a normal Cpk is only calculated on continuous data, so this is not lost.","","Incorrect — any capability index already implies data from the process."],bookRef:"Book p. 216"},{id:"sv-2-1785",phase:2,topic:"2.4.1",qtype:"concept",difficulty:2,stem:"What does the **'Expected Within Performance'** column of a capability report predict?",options:["The defects actually counted in the sample","The defect rate measured over the whole study period","The defect rate after the specification limits are widened","The defect rate if only within-subgroup variation were present"],answer:3,hint:"It is built from StDev(Within).",steps:[{title:"Key idea",body:"Expected Within PPM uses σ(within): the short-term, potential defect rate if no shifts occurred between subgroups."},{title:"Eliminate look-alikes",body:"Counted defects are observed PPM; the whole-period estimate is Expected Overall; specs are never changed."}],final:"Expected Within = short-term potential PPM → answer **D**",whyWrong:["Incorrect — counted defects are the observed performance.","Incorrect — the long-term estimate over the study is Expected Overall Performance.","Incorrect — the report always uses the entered specification limits.",""],bookRef:"Book pp. 217–219"},{id:"sv-2-1786",phase:2,topic:"2.4.1",qtype:"concept",difficulty:2,stem:"A study spans three months. Why are its Cp and Cpk still called **short-term** indices?",options:["Because they use the within-subgroup σ, whatever the time span","Because Minitab only uses the first two weeks of data","Because three months is short-term by the book’s definition","Because they include the 1.5σ shift"],answer:0,hint:"The label comes from the σ, not from the calendar.",steps:[{title:"Key idea",body:"Cp and Cpk use **σ(within)**, which excludes shifts between subgroups. They describe short-term potential even when the data cover months."},{title:"Eliminate look-alikes",body:"Minitab uses all data; three months counts as long-term data; no shift is applied."}],final:"Short-term because of σ(within) → answer **A**",whyWrong:["","Incorrect — Minitab uses every subgroup in the study.","Incorrect — the book treats a month or more as long-term data.","Incorrect — no 1.5σ shift is applied to Cp or Cpk."],bookRef:"Book pp. 213, 216"},{id:"sv-2-1787",phase:2,topic:"2.4.1",qtype:"concept",difficulty:1,stem:"Which statement about the timing of capability studies is CORRECT?",options:["A capability study is done once and remains valid for the life of the process","Capability describes the current process and must be reassessed after a process change","Capability needs to be recalculated only when the customer complains","Capability is fixed once the specification limits are agreed"],answer:1,hint:"The indices are built from today’s mean and σ.",steps:[{title:"Key idea",body:"Capability is a snapshot of the process as it runs now; after improvements or other changes the mean and σ change, so it must be **reassessed**."},{title:"Eliminate look-alikes",body:"Agreed specs and complaints do not freeze the process behaviour."}],final:"Reassess after process changes → answer **B**",whyWrong:["Incorrect — the process changes over time, so an old study may no longer describe it.","","Incorrect — waiting for complaints means defects have already reached the customer.","Incorrect — fixed specs do not fix the process mean and σ."],bookRef:"Book pp. 207, 230"},{id:"sv-2-1788",phase:2,topic:"2.4.1",qtype:"concept",difficulty:1,stem:"Which statement about **100% final inspection** and capability is CORRECT?",options:["It raises Cpk because rejected units are removed","It turns an incapable process into a capable one","It can stop defects reaching the customer but does not change process capability","It lowers Cp because more units are measured"],answer:2,hint:"Inspection sorts output; it does not change how the output is made.",steps:[{title:"Key idea",body:"Capability describes the process distribution. Inspection removes bad units **after** they are made, so the process still produces the same spread and centre."},{title:"Apply to the stem",body:"The customer is protected, but the cost of defects remains and Cpk is unchanged."}],final:"Inspection contains defects; capability unchanged → answer **C**",whyWrong:["Incorrect — removing rejects changes what ships, not how the process performs.","Incorrect — only shifting the mean or reducing variation improves capability.","","Incorrect — measuring more units does not change the process spread."],bookRef:"Book pp. 207–210"},{id:"sv-2-1789",phase:2,topic:"2.4.1",qtype:"concept",difficulty:2,stem:"Which statement about a normal process whose mean sits **exactly on one specification limit** is CORRECT?",options:["Its Cpk equals its Cp because it touches a limit","Its Cpk is negative and all output is outside the limit","Its Cpk is 1.0 because the limit is reached","Its Cpk is zero and about half of the output is outside that limit"],answer:3,hint:"The distance from the mean to that limit is zero.",steps:[{title:"Key idea",body:"Cpk = distance to the nearest limit ÷ 3σ = 0. For a normal curve centred on the limit, **half** the output lies beyond it."},{title:"Eliminate look-alikes",body:"Negative Cpk needs the mean beyond the limit; Cpk = 1 needs a 3σ gap; Cpk equals Cp only when centred."}],final:"Mean on a limit → Cpk 0, ~50% out → answer **D**",whyWrong:["Incorrect — Cpk equals Cp only when the mean is centred between the limits.","Incorrect — Cpk is negative only when the mean lies beyond the limit.","Incorrect — Cpk 1.0 means the nearest limit is 3σ from the mean.",""],bookRef:"Book p. 216"},{id:"sv-2-1790",phase:2,topic:"2.4.1",qtype:"concept",difficulty:3,stem:"Which statement about Ppk and the **1.5σ shift** is CORRECT?",options:["When real long-term data exist, Ppk measures the actual drift instead of assuming 1.5σ","Ppk is always exactly Cpk minus 0.5","Ppk can only be calculated after adding 1.5σ to the data","The 1.5σ shift is used to calculate StDev(Overall)"],answer:0,hint:"The 1.5σ is an assumption for when long-term behaviour is unknown.",steps:[{title:"Key idea",body:"The 1.5σ shift is an industry convention. When the data include real between-subgroup shifts, the **Cpk–Ppk comparison shows the actual drift**."},{title:"Eliminate look-alikes",body:"No fixed 0.5 gap exists, data are never shifted, and overall σ is the ordinary SD of all values."}],final:"Real data beat the assumed 1.5σ → answer **A**",whyWrong:["","Incorrect — the gap between Cpk and Ppk depends on the real between-subgroup variation.","Incorrect — Ppk is calculated from the data with the overall σ; nothing is added.","Incorrect — StDev(Overall) is the ordinary standard deviation of all the values."],bookRef:"Book pp. 214, 223"},{id:"sv-2-1791",phase:2,topic:"2.4.1",qtype:"concept",difficulty:2,stem:"Which statement about capability data collected **after** final inspection has removed the rejects is CORRECT?",options:["It gives the most accurate picture of the process","It understates the process spread, so the capability looks better than it is","It makes the capability look worse than the process really is","It has no effect, because rejects are rare"],answer:1,hint:"The tails beyond the limits have been cut off.",steps:[{title:"Key idea",body:"Removing rejects truncates the distribution at the specification limits, so σ is too small and the indices are **flattering**."},{title:"Apply to the stem",body:"Capability data should be collected before any sorting or screening."}],final:"Truncated data → capability overstated → answer **B**",whyWrong:["Incorrect — the data no longer contain what the process actually produced.","","Incorrect — cutting off the tails makes the spread smaller, so the result looks better, not worse.","Incorrect — even a few removed values cut the tails that drive PPM."],bookRef:"Book pp. 211–212"},{id:"sv-2-1792",phase:2,topic:"2.4.1",qtype:"concept",difficulty:1,stem:"Which statement about capability **targets** is CORRECT?",options:["A Cpk of 1.33 is required by every customer and standard","The target for Ppk is always 1.5 lower than for Cpk","1.33 is a common convention, but a customer may set its own, higher requirement","Any Cpk above 1.0 means the process meets every customer requirement"],answer:2,hint:"Thresholds are agreed, not natural laws.",steps:[{title:"Key idea",body:"The book says a Cpk of at least 1.33 is **desired**; customers and contracts can set their own targets, such as 1.67 for critical features."},{title:"Eliminate look-alikes",body:"There is no universal rule, no fixed 1.5 difference in targets, and 1.0 only just fits."}],final:"1.33 common; customers may require more → answer **C**",whyWrong:["Incorrect — 1.33 is a convention; requirements vary by customer and characteristic.","Incorrect — there is no rule that Ppk targets are 1.5 lower than Cpk targets.","","Incorrect — Cpk 1.0 leaves the nearest tail touching the limit and below most targets."],bookRef:"Book p. 225"},{id:"sv-2-1793",phase:2,topic:"2.4.1",qtype:"concept",difficulty:3,stem:"Which statement about normality testing of **very large** capability data sets is CORRECT?",options:["A large sample always passes the normality test","With large samples the normality test is no longer needed","A rejected normality test with large samples proves the indices are wrong","The Anderson-Darling test can reject normality for small departures that do not matter, so the plot should also be judged"],answer:3,hint:"The book warns that the test becomes very sensitive as N grows.",steps:[{title:"Key idea",body:"The book notes the Anderson-Darling test is **oversensitive with large N**: trivial departures give small P-values."},{title:"Apply to the stem",body:"Look at the probability plot and histogram to judge whether the departure matters in practice."}],final:"Large N: AD oversensitive; judge the plot → answer **D**",whyWrong:["Incorrect — large samples make rejection more likely, not less.","Incorrect — the assumption still matters; the test is supplemented, not dropped.","Incorrect — a tiny, practically irrelevant departure does not invalidate the indices.",""],bookRef:"Book p. 157"},{id:"sv-2-1794",phase:2,topic:"2.4.1",qtype:"concept",difficulty:2,stem:"Which statement about **gauge bias** and capability is CORRECT?",options:["Bias shifts the measured mean, so Cpk and the PPM on each side can be misstated","Bias only affects Cp, because it widens the spread","Bias has no effect on capability if the Gage R&R is acceptable","Bias makes Cpk equal to Cp"],answer:0,hint:"Bias is about location; R&R is about spread.",steps:[{title:"Key idea",body:"Bias moves every reading by a similar amount, so the **mean** used in Cpk is wrong; the process may look closer to or further from a limit than it is."},{title:"Eliminate look-alikes",body:"Spread (R&R) mainly affects Cp; a good R&R says nothing about bias."}],final:"Bias → wrong mean → wrong Cpk → answer **A**",whyWrong:["","Incorrect — bias shifts location; it is repeatability and reproducibility that widen the spread.","Incorrect — Gage R&R measures precision; bias (accuracy) must be checked separately.","Incorrect — bias moves the mean; it does not centre the process."],bookRef:"Book pp. 182–183"},{id:"sv-2-1795",phase:2,topic:"2.4.1",qtype:"statements",difficulty:2,stem:`Which statements about the book’s camshaft supplier example are CORRECT?

1. Supplier 1 had a high Cp but a low Cpk.
2. Supplier 2 was well centred but too variable.
3. The book chose Supplier 2 because its mean was centred.
4. Supplier 1’s problem was mainly variation.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Supplier 1: Cp 1.19, Cpk 0.66. Supplier 2: Cp 0.66, Cpk 0.64.",steps:[{title:"Check each statement",body:"1 true (spread fits, off-centre). 2 true (centred, Cp < 1). 3 false: the book chose Supplier 1, because moving a mean is easier. 4 false: Supplier 1 is a centring problem."},{title:"Match the pair",body:"Statements 1 and 2."}],final:"True: 1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 3 is false: the book chose Supplier 1.","Incorrect — 3 and 4 are both false.","Incorrect — statement 4 is false: Supplier 1’s Cp is fine; its problem is centring."],bookRef:"Book pp. 217–220"},{id:"sv-2-1796",phase:2,topic:"2.4.1",qtype:"statements",difficulty:2,stem:`Which statements about changing capability indices are CORRECT?

1. Widening the specification lowers Cp.
2. Reducing the within-subgroup variation raises Cp.
3. Centring an off-centre mean raises Cpk.
4. Centring an off-centre mean raises Cp.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Cp = spec width ÷ 6σ; Cpk also depends on the mean.",steps:[{title:"Check each statement",body:"1 false (wider spec raises Cp). 2 true (smaller σ). 3 true (nearest-limit distance grows). 4 false (Cp ignores the mean)."},{title:"Match the pair",body:"Statements 2 and 3."}],final:"True: 2 and 3 → answer **B**",whyWrong:["Incorrect — statement 1 is false: a wider specification increases Cp.","","Incorrect — statement 4 is false: the mean does not appear in Cp.","Incorrect — 1 and 4 are both false."],bookRef:"Book p. 216"},{id:"sv-2-1797",phase:2,topic:"2.4.1",qtype:"statements",difficulty:3,stem:`Which statements about Z.bench and sigma level are CORRECT?

1. The overall Z.bench describes long-term performance.
2. Z.bench ignores the smaller of the two tails.
3. The within Z.bench is calculated with the overall standard deviation.
4. Adding 1.5 to the overall Z.bench gives the usual short-term sigma level.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Overall = long-term; Z.bench combines both tails; the convention adds 1.5 to go to short-term.",steps:[{title:"Check each statement",body:"1 true. 2 false: both tails are combined. 3 false: within uses σ(within). 4 true: Z(ST) = Z(LT) + 1.5."},{title:"Match the pair",body:"Statements 1 and 4."}],final:"True: 1 and 4 → answer **D**",whyWrong:["Incorrect — statement 2 is false: Z.bench adds the defects from both tails.","Incorrect — 2 and 3 are both false.","Incorrect — statement 3 is false: the within Z.bench uses the within-subgroup σ.",""],bookRef:"Book pp. 219, 223"},{id:"sv-2-1798",phase:2,topic:"2.4.1",qtype:"missing-word",difficulty:3,stem:`Identify the missing word in the following sentence.

The within-subgroup standard deviation can be estimated as the average subgroup range divided by the constant [?].`,options:["A2","c4","d2","d3"],answer:2,hint:"The same constant links R̄ to σ on an Xbar-R chart.",steps:[{title:"Key idea",body:"σ(within) ≈ R̄ ÷ **d₂**, where d₂ depends on subgroup size (2.326 for n = 5)."},{title:"Eliminate look-alikes",body:"A₂ sets Xbar-chart limits, c₄ corrects a standard deviation, and d₃ relates to the spread of the range."}],final:"σ(within) = R̄ ÷ d2 → answer **C**",whyWrong:["Incorrect — A2 multiplies R̄ to place the Xbar-chart control limits.","Incorrect — c4 is the bias correction used with standard deviations, not ranges.","","Incorrect — d3 describes the standard deviation of the range, used for R-chart limits."],bookRef:"Syllabus 2.4.1"},{id:"sv-2-1799",phase:2,topic:"2.4.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The book warns that applying a normal capability analysis to clearly non-normal data is one way to [?] with statistics.`,options:["argue","guess","lie","prove"],answer:2,hint:"The book uses a well-known phrase about statistics.",steps:[{title:"Key idea",body:'Book p. 221: normal capability on non-normal data is "one way to **lie** with statistics" — the predicted PPM is wrong.'},{title:"Apply to the stem",body:"The point: check normality first."}],final:"One way to lie with statistics → answer **C**",whyWrong:['Incorrect — the book’s phrase is "lie", stressing a misleading result.','Incorrect — the book’s phrase is "lie", not "guess".',"",'Incorrect — non-normal data cannot prove anything with a normal model; the book says "lie".'],bookRef:"Book p. 221"},{id:"sv-2-1800",phase:2,topic:"2.4.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word(s) in the following sentence.

Overall (long-term) variation is made up of the within-subgroup variation plus the [?] variation.`,options:["between-subgroup","customer","specification","target"],answer:0,hint:"The book splits total variation into two parts.",steps:[{title:"Key idea",body:"Book pp. 214–215: overall variation = **between-group** + within-group variation (SS total = SS between + SS within)."},{title:"Eliminate look-alikes",body:"Customer, specification and target describe the voice of the customer, not process variation."}],final:"Overall = within + between → answer **A**",whyWrong:["","Incorrect — the customer sets requirements; they are not a component of process variation.","Incorrect — specifications are limits, not a source of variation.","Incorrect — a target is a single value chosen by the customer."],bookRef:"Book pp. 214–215"},{id:"sv-2-1801",phase:2,topic:"2.4.1",qtype:"not-except",difficulty:3,stem:"Which panel is NOT part of Minitab’s **Capability Sixpack**?",options:["A control chart of the data","A normal probability plot","A capability histogram","A Pareto chart of defect types"],answer:3,hint:"The panels check stability, normality and capability.",steps:[{title:"Key idea",body:"Sixpack panels: Xbar or I chart, R/S or MR chart, last subgroups, capability histogram, normal probability plot and capability plot."},{title:"Apply to the stem",body:"A Pareto chart ranks defect categories; it is not in the sixpack."}],final:"Pareto is NOT a sixpack panel → answer **D**",whyWrong:["Incorrect — the sixpack includes control charts to check stability.","Incorrect — the normal probability plot checks normality.","Incorrect — the capability histogram shows the data against the specs.",""],bookRef:"Syllabus 2.4.1"},{id:"sv-2-1802",phase:2,topic:"2.4.1",qtype:"not-except",difficulty:1,stem:"The last of the book’s steps to capability calculates several measures. Which is NOT one of them?",options:["Z-score","PPM","Yield","Control limits"],answer:3,hint:"The odd one out belongs to a stability tool.",steps:[{title:"Key idea",body:"Book p. 211, step 7: calculate **Z, PPM, yield, Cp, Cpk, Pp and Ppk**."},{title:"Apply to the stem",body:"Control limits are calculated for a control chart, not in the capability step."}],final:"Control limits are NOT in the capability step → answer **D**",whyWrong:["Incorrect — the Z-score is calculated in the final step.","Incorrect — PPM is calculated in the final step.","Incorrect — yield is calculated in the final step.",""],bookRef:"Book p. 211"},{id:"sv-2-1803",phase:2,topic:"2.4.1",qtype:"not-except",difficulty:1,stem:"Which action would NOT reduce StDev(Overall)?",options:["Removing differences between shifts","Centring the mean between the limits","Standardising the method across teams","Reducing the within-subgroup variation"],answer:1,hint:"Which action moves the distribution without narrowing it?",steps:[{title:"Key idea",body:"Overall σ = within + between variation. Removing between-shift and between-team differences or within noise narrows it."},{title:"Apply to the stem",body:"Centring moves the whole distribution; its spread, and so StDev(Overall), stays the same."}],final:"Centring does NOT change σ → answer **B**",whyWrong:["Incorrect — shift-to-shift differences are between-subgroup variation, part of overall σ.","","Incorrect — differing team methods add between-group variation.","Incorrect — within variation is part of overall variation, so reducing it lowers overall σ."],bookRef:"Book pp. 214–216"},{id:"sv-2-1804",phase:2,topic:"2.4.1",qtype:"scenario",difficulty:2,stem:"Four contact centres handle the same calls. The pooled Ppk for handle time is 0.90. Split by centre, A, B and C each have Ppk of about 1.5, while centre D has 0.50 with a much higher mean. Where should the team focus?",options:["On all four centres equally, because the pooled Ppk is below 1.33","On centre A, because it has the most calls","On centre D, whose different mean drags down the pooled result","On the specification, because the pooled Ppk is low"],answer:2,hint:"Stratifying capability by stream shows where the problem sits.",steps:[{title:"Key idea",body:"A pooled index mixes streams. **Per-stream capability** shows that three centres are capable and one is not."},{title:"Apply to the stem",body:"Centre D’s mean differs from the rest, so the project should study what centre D does differently."}],final:"Stratify → focus on centre D → answer **C**",whyWrong:["Incorrect — three centres are already capable; treating all equally wastes effort.","Incorrect — call volume does not make centre A the problem; its Ppk is good.","","Incorrect — the process, not the specification, is the issue in centre D."],bookRef:"Book p. 221"},{id:"sv-2-1805",phase:2,topic:"2.4.1",qtype:"scenario",difficulty:2,stem:'A connector has five critical dimensions with Cpk values of 1.9, 1.7, 1.6, 1.5 and 0.9. The plant manager reports the average, 1.52, as "the connector’s capability". Why is this misleading?',options:["Because the 0.9 dimension produces most of the defects, and an average hides it","Because Cpk values can only be averaged for two dimensions","Because an average Cpk must be multiplied by three","Because the average should use Cp instead of Cpk"],answer:0,hint:"A connector fails if any one dimension is out of specification.",steps:[{title:"Key idea",body:"Each characteristic has its own capability. The product is limited by the **weakest** one, here 0.9."},{title:"Apply to the stem",body:"Report each dimension and focus on the 0.9 one; an average suggests a capable product that does not exist."}],final:"Worst characteristic limits the product → answer **A**",whyWrong:["","Incorrect — averaging is misleading for any number of characteristics, not just above two.","Incorrect — multiplying by three converts an index into a Z value; it does not fix the averaging problem.","Incorrect — Cp ignores centring and would hide even more."],bookRef:"Book pp. 207–208"},{id:"sv-2-1806",phase:2,topic:"2.4.1",qtype:"scenario",difficulty:2,stem:"A ticketing system records any resolution time above 48 h as **exactly 48 h**. About 4% of tickets show 48 h. The team wants Ppk against a 48-hour USL. What is the main problem?",options:["There is no problem, because 48 h is the specification","The true times above 48 h are hidden, so the spread and PPM are understated","Only Cp is affected, because the mean is unchanged","The data must be treated as short-term"],answer:1,hint:"What happens to the upper tail when values are capped?",steps:[{title:"Key idea",body:"Capping cuts off the tail exactly where the defects are; σ, the mean and the predicted PPM are all wrong."},{title:"Apply to the stem",body:"Fix the data capture to record real times before the capability study."}],final:"Capped data hide the defects → answer **B**",whyWrong:["Incorrect — the cap hides how far beyond 48 h the tickets go, distorting the analysis.","","Incorrect — capping lowers both the mean and the spread, so every index is affected.","Incorrect — the time span decides short- or long-term; capping is a data-quality problem."],bookRef:"Book pp. 211–212"},{id:"sv-2-1807",phase:2,topic:"2.4.1",qtype:"scenario",difficulty:2,stem:"Customer satisfaction is collected on a **1–5 rating scale**, with a target of at least 4. The sponsor asks for Cpk. What should the Green Belt explain?",options:["Cpk can be used, because the ratings are numbers","Cp can be used instead, because it ignores the mean","Ordinal ratings do not suit a normal Cpk; an attribute measure such as the share of low ratings fits better","Only a Box-Cox transformation is needed before Cpk"],answer:2,hint:"Can a mean and standard deviation of 1–5 ratings describe a continuous distribution?",steps:[{title:"Key idea",body:"Normal capability needs **continuous** data. Five ordered categories are ordinal; their mean and σ do not describe a normal curve."},{title:"Apply to the stem",body:"Count ratings below 4 as defectives and use an attribute (proportion) measure."}],final:"Ordinal data → attribute measure → answer **C**",whyWrong:["Incorrect — numbers on an ordinal scale are labels for ordered categories, not measurements.","Incorrect — Cp has the same continuous-data requirement as Cpk.","","Incorrect — a transformation cannot turn five categories into continuous data."],bookRef:"Book pp. 144, 211"},{id:"sv-2-1808",phase:2,topic:"2.4.1",qtype:"scenario",difficulty:3,stem:"A new billing system went live three months ago. For the capability baseline, the team can use the last 6 months, the last 2 weeks, the 3 months since go-live, or the best month since go-live. Which is the BEST choice?",options:["The last 6 months","The last 2 weeks","The best month since go-live","The 3 months since go-live"],answer:3,hint:"The baseline must be long-term and describe the process as it runs now.",steps:[{title:"Key idea",body:"A baseline must be **long-term** and must represent the **current** process."},{title:"Apply to the stem",body:"Six months mixes the old system in; two weeks is short-term; the best month is entitlement. Three months since go-live meets both needs."}],final:"Current and long-term → since go-live → answer **D**",whyWrong:["Incorrect — half of this period comes from the old system, so it mixes two processes.","Incorrect — two weeks is short-term data, not a baseline.","Incorrect — choosing the best month shows entitlement, not the baseline.",""],bookRef:"Book pp. 213–214"},{id:"sv-2-1809",phase:2,topic:"2.4.1",qtype:"scenario",difficulty:2,stem:"Food packs must legally not weigh less than the declared minimum (LSL); overfilling above the USL only costs money. Which index BEST shows the long-term risk of breaking the law?",options:["Cp","CPU","Pp","PPL"],answer:3,hint:"Long-term, and the lower side only.",steps:[{title:"Key idea",body:"The legal risk lies **below the LSL**, and compliance applies over time, so the lower-side **overall** index matters."},{title:"Eliminate look-alikes",body:"Cp and Pp ignore centring and both sides; CPU is the upper, short-term side."}],final:"Long-term lower side = PPL → answer **D**",whyWrong:["Incorrect — Cp ignores centring and does not show which side is at risk.","Incorrect — CPU covers the upper (cost) side and uses short-term σ.","Incorrect — Pp ignores where the mean sits relative to the LSL.",""],bookRef:"Book pp. 212, 216"},{id:"sv-2-1810",phase:2,topic:"2.4.1",qtype:"best-action",difficulty:1,stem:'The sponsor wants a Cpk for "time to quote", but no requirement has ever been agreed with customers. What should the Green Belt do FIRST?',options:["Agree the requirement with the customer or business owner","Use the control limits as specification limits","Use mean ± 3σ of the current data as the specification","Use the best month’s results as the specification"],answer:0,hint:"No voice of the customer, no capability.",steps:[{title:"Key idea",body:"Capability compares the process with the **voice of the customer**. Without a valid specification there is nothing to compare against."},{title:"Apply to the stem",body:'Establish and validate the requirement first; anything taken from the process data would make the process "capable" by definition.'}],final:"First agree the requirement → answer **A**",whyWrong:["","Incorrect — control limits are the voice of the process, not a customer requirement.","Incorrect — mean ± 3σ is the natural tolerance; using it as a spec makes Cp 1.0 by definition.","Incorrect — past best performance is entitlement, not what the customer needs."],bookRef:"Book pp. 211–212"},{id:"sv-2-1811",phase:2,topic:"2.4.1",qtype:"best-action",difficulty:2,stem:"Three capability values looked impossible. The Green Belt checked them against the source records, found they were keying errors, corrected them and re-ran the study. Was this an appropriate action?",options:["Yes, because verified recording errors are not process output and should be corrected","Yes, because any extreme value may be removed to improve the result","No, because data values must never be changed once collected","No, because extreme values must always be kept, even when they are wrong"],answer:0,hint:"Contrast correcting a proven error with deleting an inconvenient value.",steps:[{title:"Key idea",body:"Real but unwelcome values must stay in the study. A **verified recording error** is not what the process produced, so correcting it gives a truer picture."},{title:"Apply to the stem",body:"The values were checked against the source, so the correction is justified and should be documented."}],final:"Yes — verified errors are corrected → answer **A**",whyWrong:["","Incorrect — removing values only because they hurt the result misstates the process.","Incorrect — a proven keying error should be fixed; keeping it misrepresents the process.","Incorrect — keeping values known to be wrong distorts σ and PPM."],bookRef:"Book pp. 211–212"},{id:"sv-2-1812",phase:2,topic:"2.4.1",qtype:"best-action",difficulty:2,stem:"The capability data set for invoice cycle time mixes two invoice types that have **different** contractual limits (3 days and 10 days). What is the BEST action?",options:["Use the wider 10-day limit for all invoices","Analyse each invoice type against its own specification","Average the two limits and use 6.5 days","Use the tighter 3-day limit for all invoices"],answer:1,hint:"Each characteristic is compared with its own customer requirement.",steps:[{title:"Key idea",body:"Capability compares a process with **its** specification. Two types with different limits are two capability questions."},{title:"Apply to the stem",body:"Split the data by type and run a study for each against its contractual limit."}],final:"Separate studies, own specs → answer **B**",whyWrong:["Incorrect — the 3-day invoices would be judged against a limit their customers never agreed.","","Incorrect — an averaged limit is not anyone’s requirement.","Incorrect — the 10-day invoices would be judged against a limit that does not apply to them."],bookRef:"Book p. 212"},{id:"sv-2-1813",phase:2,topic:"2.4.1",qtype:"best-action",difficulty:2,stem:"In Measure, a capability study shows Cpk = 0.6. The Green Belt immediately proposes buying a new machine. Was this an appropriate action?",options:["Yes, because a Cpk below 1.0 always requires new equipment","Yes, because the capability study has identified the root cause","No, because the indices should first show whether the issue is centring, spread or drift, and the X’s be found in Analyze","No, because a Cpk of 0.6 already meets the usual target"],answer:2,hint:"Capability says what kind of problem exists, not what causes it.",steps:[{title:"Key idea",body:"Comparing Cp, Cpk and Ppk shows whether the problem is **centring, spread or drift**; the causes are proven in Analyze before a solution is chosen."},{title:"Apply to the stem",body:"If it is a centring problem, a simple adjustment may be enough; a new machine may be unnecessary."}],final:"No — diagnose and find X’s first → answer **C**",whyWrong:["Incorrect — low Cpk may be a simple centring problem that needs no new equipment.","Incorrect — capability does not identify root causes; that is the Analyze phase.","","Incorrect — 0.6 is far below the usual 1.33 target."],bookRef:"Book pp. 207–210"},{id:"sv-2-1814",phase:2,topic:"2.4.1",qtype:"output",difficulty:3,stem:`A supplier submits this result (normal data, stable process):

\`\`\`
Process Capability Report for Bracket Width (mm)
Sample N   30
Cpk        1.41     95% CI for Cpk (1.03, 1.79)
Ppk        1.38
\`\`\`

The contract requires Cpk ≥ 1.33. Can the requirement be claimed with confidence?`,options:["Yes, because the estimate 1.41 is above 1.33","Yes, because the upper confidence bound 1.79 is above 1.33","No, because the lower confidence bound 1.03 is below 1.33, so more data are needed","No, because Ppk is lower than Cpk"],answer:2,hint:"A capability index is an estimate from a sample.",steps:[{title:"Read the output",body:"With only 30 values the 95% interval runs from 1.03 to 1.79; the true Cpk could be well below 1.33."},{title:"Decide",body:"The point estimate passes, but the requirement cannot be claimed with confidence; collect more data."}],final:"Lower bound < 1.33 → not proven → answer **C**",whyWrong:["Incorrect — the estimate is uncertain; the interval includes values well below 1.33.","Incorrect — the upper bound shows the best case, not what can be relied on.","","Incorrect — Ppk slightly below Cpk is normal and not the issue."],bookRef:"Syllabus 2.4.1"},{id:"sv-2-1815",phase:2,topic:"2.4.1",qtype:"output",difficulty:3,stem:`Each subgroup of 5 contains one bottle from **each of five filling nozzles**:

\`\`\`
Process Capability Report for Fill Volume (ml)
LSL 20.00  USL 35.00  Sample Mean 27.50  Subgroup size 5
StDev(Within)   2.30     Cp 1.09   Cpk 1.09
StDev(Overall)  1.85     Pp 1.35   Ppk 1.35
\`\`\`

What is the MOST likely explanation for StDev(Within) being **larger** than StDev(Overall)?`,options:["The process drifts strongly between subgroups over time","The data are not normally distributed","The specification limits were entered the wrong way round","The subgroups mix the nozzles, so nozzle-to-nozzle differences are counted as within-subgroup variation"],answer:3,hint:"Within σ should hold only short-term noise from one source.",steps:[{title:"Read the output",body:"Normally σ(within) ≤ σ(overall). Here it is larger, so something extra sits **inside** the subgroups."},{title:"Decide",body:"Each subgroup takes one bottle per nozzle, so nozzle differences are inside every subgroup: the subgroups are not rational."}],final:"Non-rational subgroups inflate within σ → answer **D**",whyWrong:["Incorrect — drift between subgroups would make overall σ larger, not smaller.","Incorrect — non-normality affects the fit, not the order of the two σ estimates.","Incorrect — swapped limits would give an error or negative indices.",""],bookRef:"Book pp. 212–215"},{id:"sv-2-1816",phase:2,topic:"2.4.1",qtype:"output",difficulty:2,stem:`Response time has an upper limit only (USL 60 ms):

\`\`\`
Process Capability Report for Response Time (ms)
Sample Mean 45.0   StDev(Within) 4.0   StDev(Overall) 5.6
Cpk 1.25   Ppk 0.89
Expected Within PPM > USL     88.42
Expected Overall PPM > USL  3696.85
\`\`\`

Which action would cut the **long-term** PPM the most?`,options:["Find and remove the causes of shifts between subgroups","Widen the upper limit with the customer","Reduce the within-subgroup variation only","Set the control limits closer to the mean"],answer:0,hint:"Compare the within and overall PPM figures.",steps:[{title:"Read the output",body:"With only within variation, about 88 PPM would exceed the USL; with the real long-term variation, about 3,700 PPM do."},{title:"Decide",body:"Most long-term defects come from **between-subgroup shifts**, so controlling them gives the biggest gain."}],final:"Remove between-subgroup shifts → answer **A**",whyWrong:["","Incorrect — widening the limit changes the requirement, not the process, and needs customer agreement.","Incorrect — short-term variation already gives only about 88 PPM; the extra defects come from shifts.","Incorrect — control limits are calculated from data and do not change the output."],bookRef:"Book pp. 216–219"},{id:"sv-2-1817",phase:2,topic:"2.4.1",qtype:"output",difficulty:3,stem:`Two processes share the same specification:

\`\`\`
Process  Cp    Cpk   Exp PPM<LSL  Exp PPM>USL  Exp PPM Total
A        1.00  1.00   1349.90      1349.90      2699.80
B        1.80  1.00      0.00      1349.90      1349.90
\`\`\`

Which statement is CORRECT?`,options:["A and B have the same defect rate, because their Cpk values are equal","A loses output on both sides, so it has more defects despite the same Cpk","B has more defects, because it is off-centre","B is a variation problem and A is a centring problem"],answer:1,hint:"Equal Cpk only means the nearer tail is the same.",steps:[{title:"Read the output",body:"Both nearer tails give 1,349.90 PPM. A is centred with Cp 1.00, so its far tail adds the same again; B’s far tail is empty."},{title:"Decide",body:"A has about twice the defects of B although both have Cpk 1.00."}],final:"Same Cpk, different PPM → answer **B**",whyWrong:["Incorrect — the PPM totals differ; Cpk describes only the nearer limit.","","Incorrect — B’s total, 1,349.90, is lower than A’s 2,699.80.","Incorrect — it is the reverse: A (Cp = Cpk = 1.00) is a variation problem, B (high Cp, low Cpk) a centring problem."],bookRef:"Book pp. 216–219"},{id:"sv-2-1818",phase:2,topic:"2.4.1",qtype:"output",difficulty:3,stem:`Port-in time is skewed, so the team fits a distribution:

\`\`\`
Process Capability Report for Port-In Time (h)
Calculations Based on Weibull Distribution Model
LSL *   USL 48.00   Sample N 220
Shape 1.85   Scale 21.40

Overall Capability      Exp. Overall Performance
Pp   *                  PPM > USL   11600
PPU  0.73
Ppk  0.73
\`\`\`

Which statement about this report is CORRECT?`,options:["Ppk is invalid, because the data are not normal",'Pp shows "*" because the data are not normal',"It gives only overall (long-term) indices, because the Weibull model is fitted to all the data","The PPM is predicted from a fitted normal curve"],answer:2,hint:"Look at which sections the report contains and why Pp is missing.",steps:[{title:"Read the output",body:'A non-normal (Weibull) analysis models all the data, so it reports **overall** indices only; Pp is "*" because there is no LSL.'},{title:"Decide",body:"Ppk 0.73 and about 11,600 PPM are valid estimates under the fitted Weibull model."}],final:"Non-normal capability = overall indices only → answer **C**",whyWrong:["Incorrect — fitting a suitable distribution is a valid way to handle non-normal data.","Incorrect — Pp needs two limits; it is missing because there is no LSL.","","Incorrect — the report states the Weibull model is used, not a normal curve."],bookRef:"Syllabus 2.4.1"},{id:"sv-2-1819",phase:2,topic:"2.4.1",qtype:"output",difficulty:3,stem:`Battery charge time (LSL 10 min, USL 30 min):

\`\`\`
Process Capability Report for Charge Time (min)
Sample Mean 20.00   StDev(Within) 3.51   StDev(Overall) 4.76
Cp  0.95   Cpk 0.95
Pp  0.70   Ppk 0.70
\`\`\`

Which combination of problems does the report show?`,options:["The mean is off-centre, but the spread is acceptable","Only shifts over time; the short-term spread is acceptable","Only the spread is too wide; there are no shifts over time","Centring is fine, but the spread is too wide and the process also shifts over time"],answer:3,hint:"Compare Cp with Cpk, Cp with 1, and Cpk with Ppk.",steps:[{title:"Read the output",body:"Cp = Cpk (centred). Cp 0.95 < 1 (spread too wide even short-term). Cpk 0.95 > Ppk 0.70 (shifts between subgroups)."},{title:"Decide",body:"Two problems: variation and drift; centring is not an issue."}],final:"Spread + drift, centred → answer **D**",whyWrong:["Incorrect — Cp equals Cpk, so the mean is centred; and Cp < 1 means the spread is not acceptable.","Incorrect — Cp 0.95 is below 1, so short-term spread is also too wide.","Incorrect — the drop from Cpk 0.95 to Ppk 0.70 shows shifts over time.",""],bookRef:"Book p. 216"},{id:"sv-2-1820",phase:2,topic:"2.4.1",qtype:"output",difficulty:2,stem:`Three vendors report capability for the same installation service:

\`\`\`
Vendor  Index reported  Value  Data behind it
V1      Ppk             1.45   2 weeks, one site
V2      Ppk             1.20   6 months, all sites
V3      Cpk             1.60   6 months, all sites
\`\`\`

Which figure is valid evidence of **long-term delivered** performance?`,options:["V1’s Ppk of 1.45","V2’s Ppk of 1.20","V3’s Cpk of 1.60","All three, because each is above 1.0"],answer:1,hint:"Check both the index and the data behind it.",steps:[{title:"Read the output",body:"V1’s data are two weeks at one site (short-term). V3 reports Cpk, which uses within σ (short-term). V2 reports Ppk on six months across all sites."},{title:"Decide",body:"Only V2’s figure describes long-term delivered performance; it may be lower simply because it is the honest long-term number."}],final:"Long-term index + long-term data = V2 → answer **B**",whyWrong:["Incorrect — two weeks at one site is short-term data, whatever the index is called.","","Incorrect — Cpk uses the within-subgroup σ, so it shows short-term potential.","Incorrect — the figures are not comparable, and only one is long-term evidence."],bookRef:"Book pp. 212–216"},{id:"sv-2-1821",phase:2,topic:"2.4.1",qtype:"sequence",difficulty:2,stem:`Put the steps of a Box-Cox capability analysis in order:

- **P** Transform the data and the specification limits with λ
- **Q** Confirm that all values are positive
- **R** Find the best λ for the data
- **S** Calculate the indices on the transformed scale`,options:["Q → R → P → S","R → Q → P → S","Q → P → R → S","R → P → Q → S"],answer:0,hint:"Check the data condition, choose λ, transform, then calculate.",steps:[{title:"Key idea",body:"Box-Cox needs positive data; λ is then estimated; data **and** specs are transformed with it; finally the indices are calculated."},{title:"Apply to the stem",body:"Q → R → P → S."}],final:"Positive → λ → transform → indices → answer **A**",whyWrong:["","Incorrect — the positive-data condition must be confirmed before λ is estimated.","Incorrect — the data cannot be transformed before λ has been found.","Incorrect — positive data must be confirmed first, and λ is needed before transforming."],bookRef:"Syllabus 2.4.1"},{id:"sv-2-1822",phase:2,topic:"2.4.1",qtype:"sequence",difficulty:2,stem:`Put these preparations for a capability study in order:

- **P** Collect the data in time order, keeping the subgroups
- **Q** Agree the operational definition of the measurement
- **R** Run the capability analysis
- **S** Confirm the measurement system is adequate`,options:["S → Q → P → R","Q → P → S → R","Q → S → P → R","P → Q → S → R"],answer:2,hint:"Define what to measure, check the gauge, collect, then analyse.",steps:[{title:"Key idea",body:"Agree **what** is measured and how; check the gauge can measure it; collect data in order; then analyse."},{title:"Apply to the stem",body:"Q → S → P → R."}],final:"Define → MSA → collect → analyse → answer **C**",whyWrong:["Incorrect — the MSA needs an agreed operational definition of what is measured.","Incorrect — data collected before the gauge is confirmed may have to be thrown away.","","Incorrect — data cannot be collected before the measurement is defined."],bookRef:"Book pp. 172, 211, 230"},{id:"sv-2-1823",phase:2,topic:"2.4.2",qtype:"concept",difficulty:1,stem:"What can be predicted about a process that is **stable**?",options:["The exact value of the next measurement","That it will meet the specification limits","That it will never show a special cause","The range within which its future output is likely to fall"],answer:3,hint:"Stable means predictable — but within limits, not exactly.",steps:[{title:"Key idea",body:"With only common causes present, future values fall **within predictable limits** (the control limits)."},{title:"Eliminate look-alikes",body:"Individual values still vary randomly, meeting specs is capability, and a special cause can appear later."}],final:"Stable → predictable range → answer **D**",whyWrong:["Incorrect — common-cause variation makes each individual value unpredictable.","Incorrect — whether output meets specs is capability, not stability.","Incorrect — stability today does not stop a new special cause from appearing.",""],bookRef:"Book pp. 211, 517"},{id:"sv-2-1824",phase:2,topic:"2.4.2",qtype:"concept",difficulty:1,stem:"What does the book say about variation in processes?",options:["It exists in everything and cannot be removed completely","It can be removed completely in a stable process","It exists only when special causes are present","It is always a sign that the process is out of control"],answer:0,hint:"Even a perfect process is not perfectly repeatable.",steps:[{title:"Key idea",body:"Book p. 209: variation **exists in everything** and cannot be removed completely; it can be reduced and, if small and stable, tolerated."},{title:"Eliminate look-alikes",body:"A stable process still has common-cause variation, which is not a sign of being out of control."}],final:"Variation is everywhere → answer **A**",whyWrong:["","Incorrect — a stable process still has common-cause variation.","Incorrect — common-cause variation is present even with no special causes.","Incorrect — random common-cause variation is normal in an in-control process."],bookRef:"Book p. 209"},{id:"sv-2-1825",phase:2,topic:"2.4.2",qtype:"concept",difficulty:2,stem:"The average of a process stays constant, but its spread grows steadily week after week. Is the process stable?",options:["Yes, because the average has not changed","No, because stability requires both the centre and the spread to be consistent","Yes, because a growing spread is common-cause variation","No, because the average must always decrease"],answer:1,hint:"Predictable behaviour covers location and variation.",steps:[{title:"Key idea",body:"A stable process is consistent in **both** its location and its variation. A steadily growing spread is a non-random change."},{title:"Apply to the stem",body:"It would show on the range or moving-range chart, so the process is not stable."}],final:"Spread changing → not stable → answer **B**",whyWrong:["Incorrect — a constant average is not enough; the variation must also be consistent.","","Incorrect — a steady growth in spread is a systematic change, not random noise.","Incorrect — stability does not require any direction of change in the average."],bookRef:"Book pp. 211, 517"},{id:"sv-2-1826",phase:2,topic:"2.4.2",qtype:"concept",difficulty:1,stem:"A KPI produces **one value per day**. Which control chart is normally used to check its stability?",options:["I-MR chart","Xbar-R chart","p chart","c chart"],answer:0,hint:"One continuous value per period.",steps:[{title:"Key idea",body:"One continuous measurement per period → **Individuals and Moving Range** chart."},{title:"Eliminate look-alikes",body:"Xbar-R needs subgroups; p and c charts are for attribute data."}],final:"One value per day → I-MR → answer **A**",whyWrong:["","Incorrect — Xbar-R needs subgroups of several values per period.","Incorrect — a p chart is for proportion defective (attribute data).","Incorrect — a c chart is for counts of defects (attribute data)."],bookRef:"Book pp. 525–530"},{id:"sv-2-1827",phase:2,topic:"2.4.2",qtype:"concept",difficulty:1,stem:"Which is an advantage of a **run chart** over a control chart for a first look at stability?",options:["It shows whether the output meets the specification","It proves that the process is capable","It needs no standard deviation estimate or control limits","It removes the need for data in time order"],answer:2,hint:"A run chart plots the data around the median.",steps:[{title:"Key idea",body:"A run chart uses only the **median** and the time order, so it is quick and works with small data sets."},{title:"Eliminate look-alikes",body:"Neither chart judges specs or capability, and both need time order."}],final:"Run chart = no σ or limits needed → answer **C**",whyWrong:["Incorrect — specification limits do not belong on stability charts.","Incorrect — capability is judged against the specification, not on a run chart.","","Incorrect — a run chart depends on time order just as a control chart does."],bookRef:"Book pp. 167, 215"},{id:"sv-2-1828",phase:2,topic:"2.4.2",qtype:"concept",difficulty:2,stem:"Why does a control chart used for a stability check need a **centre line**?",options:["To show the customer’s target value","To mark the specification mid-point","To show where the next value will fall","To judge runs of points on one side, such as 9 in a row"],answer:3,hint:"Several special-cause rules count points relative to it.",steps:[{title:"Key idea",body:"The centre line is the process average. Rules such as **9 points in a row on one side** need it to detect shifts."},{title:"Eliminate look-alikes",body:"Targets and spec mid-points are customer values; the next value cannot be predicted exactly."}],final:"Centre line → judge runs and shifts → answer **D**",whyWrong:["Incorrect — the centre line is the process average, not a customer target.","Incorrect — specification values never belong on a control chart.","Incorrect — individual future values vary randomly around the centre line.",""],bookRef:"Book pp. 525, 532–533"},{id:"sv-2-1829",phase:2,topic:"2.4.2",qtype:"concept",difficulty:2,stem:"Which statement about the **width** of control limits is CORRECT?",options:["Wide limits reflect large common-cause variation; the process can still be stable","Wide limits prove that special causes are present","Wide limits mean the process is capable","Wide limits mean the specification is too loose"],answer:0,hint:"Stability is about patterns, not about the size of the variation.",steps:[{title:"Key idea",body:"Limits are calculated from the data, so their width shows **how much** common-cause variation exists. Stability is the absence of special-cause signals."},{title:"Eliminate look-alikes",body:"Width says nothing about special causes, capability or the specification."}],final:"Wide limits ≠ unstable → answer **A**",whyWrong:["","Incorrect — special causes show as signals and patterns, not as wide limits.","Incorrect — wide limits usually mean a lot of variation, which makes capability worse.","Incorrect — control limits are not compared with the specification on the chart."],bookRef:"Book pp. 517, 524–527"},{id:"sv-2-1830",phase:2,topic:"2.4.2",qtype:"concept",difficulty:3,stem:"Which statement about unresolved special causes in capability data is CORRECT?",options:["They lower Cp but leave Ppk unchanged","They inflate the overall standard deviation, so Ppk understates the entitlement","They have no effect on capability if the data are normal","They make Ppk larger than Cpk"],answer:1,hint:"Special causes usually act between subgroups.",steps:[{title:"Key idea",body:"Shifts and outliers from special causes add **between-subgroup** variation, which is in σ(overall) but mostly not in σ(within)."},{title:"Apply to the stem",body:"Ppk is pulled down, while Cpk shows what the process could do without them."}],final:"Special causes → bigger σ(overall) → lower Ppk → answer **B**",whyWrong:["Incorrect — Cp uses within σ, which special causes between subgroups barely affect; Ppk drops.","","Incorrect — normality does not cancel the extra variation added by special causes.","Incorrect — the extra variation makes Ppk smaller than Cpk, not larger."],bookRef:"Book pp. 212, 216"},{id:"sv-2-1831",phase:2,topic:"2.4.2",qtype:"statements",difficulty:2,stem:`Which statements about stability and capability are CORRECT?

1. A stable and capable process is the ideal case.
2. A stable process has only common-cause variation.
3. A stable process always meets the specification.
4. A capable process is always stable.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Stability and capability are independent questions.",steps:[{title:"Check each statement",body:"1 true: predictable and meets specs. 2 true: the definition of stability. 3 false: a stable process can predictably miss specs. 4 false: a process can meet specs now and be unstable."},{title:"Match the pair",body:"Statements 1 and 2."}],final:"True: 1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 3 is false: stable is not the same as capable.","Incorrect — 3 and 4 are both false.","Incorrect — statement 4 is false: meeting specs today does not make a process predictable."],bookRef:"Book p. 518"},{id:"sv-2-1832",phase:2,topic:"2.4.2",qtype:"not-except",difficulty:1,stem:"Which is NOT needed to assess whether a process is stable?",options:["Data recorded in time order","A centre line from the data","Control limits calculated from the data","The specification limits"],answer:3,hint:"Stability uses only the voice of the process.",steps:[{title:"Key idea",body:"A stability check needs time-ordered data, a centre line and control limits from the **process**."},{title:"Apply to the stem",body:"Specification limits are the voice of the customer; they are needed for capability, not stability."}],final:"Specs are NOT needed for stability → answer **D**",whyWrong:["Incorrect — without time order, shifts and trends cannot be seen.","Incorrect — the centre line is needed to judge runs and shifts.","Incorrect — control limits are the yardstick for special-cause signals.",""],bookRef:"Book pp. 215, 524"},{id:"sv-2-1833",phase:2,topic:"2.4.2",qtype:"not-except",difficulty:1,stem:"Which action would NOT help make an unstable process stable?",options:["Investigating each signal for an assignable cause","Standardising the work method","Adjusting the process after every measurement","Controlling a known input such as the material lot"],answer:2,hint:"One action reacts to noise.",steps:[{title:"Key idea",body:"Stability improves when special causes are found, removed and prevented — by standard methods and controlled inputs."},{title:"Apply to the stem",body:"Adjusting after every point reacts to common-cause noise (tampering) and adds variation."}],final:"Tampering does NOT help → answer **C**",whyWrong:["Incorrect — investigating signals is how special causes are found.","Incorrect — standard methods remove a common source of special causes.","","Incorrect — controlling a known input prevents it from causing shifts."],bookRef:"Book p. 544"},{id:"sv-2-1834",phase:2,topic:"2.4.2",qtype:"scenario",difficulty:3,stem:"Each morning a technician measures the same **reference standard** on the production gauge. The chart of these readings shows a steady upward trend over three weeks. What does this indicate?",options:["The measurement system is drifting, so its stability must be fixed","The production process is drifting upwards","The process is stable, because the same part is measured","The specification limits need to be widened"],answer:0,hint:"The part never changes — so what does?",steps:[{title:"Key idea",body:"A reference standard has a fixed true value. A trend in its readings is **measurement stability** (bias changing over time), not process instability."},{title:"Apply to the stem",body:"Recalibrate or repair the gauge before trusting process stability or capability data."}],final:"Measurement drift, not process drift → answer **A**",whyWrong:["","Incorrect — the same reference part is measured, so the process cannot be the cause.","Incorrect — the readings trend, so the measurement system is not stable.","Incorrect — the specs are unrelated to a drifting gauge."],bookRef:"Book p. 183"},{id:"sv-2-1835",phase:2,topic:"2.4.2",qtype:"scenario",difficulty:1,stem:"A new KPI has only **8 daily values** so far, all within the trial control limits. The sponsor wants the process declared stable. What should the Green Belt say?",options:["The process is stable, because no point is outside the limits","Eight points are too few to judge stability; keep collecting over a longer period","The process is unstable, because the limits are trial limits","Stability can be declared if the points are normal"],answer:1,hint:"Patterns such as 9 in a row cannot even appear yet.",steps:[{title:"Key idea",body:"Stability is judged on enough time-ordered data for the special-cause rules to work; with 8 points, several rules cannot even fire."},{title:"Apply to the stem",body:"Continue collecting, then reassess."}],final:"Too few points to judge → answer **B**",whyWrong:["Incorrect — with 8 points, runs and trends cannot be judged; no signal is weak evidence.","","Incorrect — trial limits are normal at the start; they do not prove instability.","Incorrect — normality says nothing about stability over time."],bookRef:"Book pp. 215, 532–533"},{id:"sv-2-1836",phase:2,topic:"2.4.2",qtype:"best-action",difficulty:1,stem:"A team is collecting three months of baseline data on order-processing time. During this period a system upgrade, a staff change and a supplier strike are expected. What is the BEST practice?",options:["Stop collecting data whenever an event occurs","Delete the data from event days afterwards","Log each event with its date so chart signals can be linked to causes","Ignore the events, because they will average out"],answer:2,hint:"The book asks whether special causes have been acknowledged.",steps:[{title:"Key idea",body:"Special causes must be **acknowledged** and studied. Recording events alongside the data lets the team explain signals on the chart."},{title:"Eliminate look-alikes",body:"Stopping, deleting or ignoring hides real behaviour of the process."}],final:"Log events beside the data → answer **C**",whyWrong:["Incorrect — gaps hide how the process behaves when such events happen.","Incorrect — deleting days hides special causes instead of acknowledging them.","","Incorrect — special causes do not average out; they distort the baseline."],bookRef:"Book p. 231"},{id:"sv-2-1837",phase:2,topic:"2.4.2",qtype:"best-action",difficulty:2,stem:"A team found and removed the cause of repeated outages that made its process unstable. What should it do FIRST before using capability to predict performance?",options:["Report the old capability, since the cause is gone","Recalculate the capability using the old data without the outage days","Widen the control limits to allow for future outages","Collect new data and confirm on a control chart that the process is now stable"],answer:3,hint:"Prediction needs evidence of stability, not just an assumption.",steps:[{title:"Key idea",body:"Removing a cause is a process change. Stability must be **shown with new data** before capability is used as a prediction."},{title:"Eliminate look-alikes",body:"Old data describe the old process; limits are never widened to absorb signals."}],final:"Confirm stability with new data → answer **D**",whyWrong:["Incorrect — the old capability describes the process before the fix.","Incorrect — editing old data is not evidence that the changed process is stable.","Incorrect — control limits are calculated from data, not widened.",""],bookRef:"Book pp. 211, 230"},{id:"sv-2-1838",phase:2,topic:"2.4.2",qtype:"output",difficulty:2,stem:`Before a capability study, the team checks call-transfer time:

\`\`\`
Test Results for I Chart of Transfer Time (s)
TEST 4. 14 points in a row alternating up and down.
Test Failed at points: 23, 24

No point lies outside the control limits.
\`\`\`

Which conclusion is CORRECT?`,options:["The process is not stable: the alternating pattern is non-random, for example from over-adjustment or two alternating sources","The process is stable, because no point is outside the limits","The process is stable, because alternating points cancel out","The process is capable, because the points stay inside the limits"],answer:0,hint:"Signals include patterns, not only points beyond the limits.",steps:[{title:"Read the output",body:"Test 4 (14 alternating) failed: a non-random oscillation."},{title:"Decide",body:"The process is not stable even though all points are inside the limits; look for over-adjustment or two alternating streams."}],final:"Test 4 → not stable → answer **A**",whyWrong:["","Incorrect — run rules detect special causes even when every point is inside the limits.","Incorrect — a regular alternating pattern is itself the signal.","Incorrect — capability is judged against specs, which are not on this chart."],bookRef:"Book pp. 532–533"},{id:"sv-2-1839",phase:2,topic:"2.4.2",qtype:"output",difficulty:2,stem:`The I chart of daily backlog for a stability check shows:

\`\`\`
Test Results for I Chart of Daily Backlog
TEST 2. 9 points in a row on same side of center line.
Test Failed at points: 29, 30, 31
\`\`\`

At which observation did the shift MOST likely begin?`,options:["21","29","30","31"],answer:0,hint:"Test 2 is flagged on the ninth point of the run.",steps:[{title:"Read the output",body:"Point 29 is the first flag, so it is the **ninth** point of the run on one side."},{title:"Decide",body:"The run, and so the shift, started eight points earlier, at observation 21. Investigate what changed around then."}],final:"Run of 9 ending at 29 starts at 21 → answer **A**",whyWrong:["","Incorrect — 29 is where the test first fires, the ninth point of the run, not its start.","Incorrect — 30 is a later point of the same run.","Incorrect — 31 is the latest flagged point of the run."],bookRef:"Book pp. 532–533"},{id:"sv-2-1840",phase:2,topic:"2.4.2",qtype:"sequence",difficulty:2,stem:`A process is **neither stable nor capable**. Put the work in a sensible order:

- **P** Confirm capability against the specification
- **Q** Find and remove the special causes
- **R** Reduce the common-cause variation or centre the mean
- **S** Confirm the process is stable`,options:["R → Q → S → P","Q → S → R → P","Q → R → P → S","S → Q → R → P"],answer:1,hint:"Worst case: stability first, then capability.",steps:[{title:"Key idea",body:"In the worst quadrant, **remove special causes first** and confirm stability; then improve the system for capability and confirm it."},{title:"Apply to the stem",body:"Q → S → R → P."}],final:"Special causes → stable → improve → capable → answer **B**",whyWrong:["Incorrect — improving common-cause variation first is hard to judge while special causes distort the data.","","Incorrect — stability must be confirmed before capability can be trusted.","Incorrect — stability cannot be confirmed before the special causes are removed."],bookRef:"Book pp. 211, 518"}];export{e as items};
